export function useTransitData(agency = "caltrain") {
  const [data, setData] = useState<TransitTrip[]>([]);
  const [loading, setLoading] = useState(true);
  const [prevAgency, setPrevAgency] = useState(agency);

  if (agency !== prevAgency) {
    setPrevAgency(agency);
    setLoading(true);
  }

  useEffect(() => {
    // Simulate initial fetch with a slight delay
    const timer = setTimeout(() => {
      setData(agency === "ttc" ? TTC_MOCK : CALTRAIN_MOCK);
      setLoading(false);
    }, 800);

    // Simulate occasional updates or status changes
    const interval = setInterval(() => {
      setData((current) =>
        current.map((trip) => {
          if (Math.random() > 0.85) {
            const statuses: TransitTrip["status"][] = [
              "ON TIME",
              "DELAYED",
              "BOARDING",
              "DEPARTED",
            ];
            return {
              ...trip,
              status: statuses[Math.floor(Math.random() * statuses.length)],
            };
          }
          return trip;
        })
      );
    }, 12_000);

    return () => {
      clearTimeout(timer);
      clearInterval(interval);
    };
  }, [agency]);

  return { data, loading };
}

import { ALPHANUMERIC_SET, CHAR_SET, NUMERIC_SET, TIME_SET } from "./constants";

export function sanitizeChar(char: string, charSet: string = CHAR_SET): string {
  const sanitized = char.toUpperCase();
  return charSet.includes(sanitized) ? sanitized : " ";
}

export function getSafeIndex(char: string, charSet: string = CHAR_SET): number {
  const index = charSet.indexOf(char);
  return index === -1 ? 0 : index;
}

export function getNextChar(
  currentChar: string,
  charSet: string = CHAR_SET
): string {
  const currentIndex = getSafeIndex(currentChar, charSet);
  const nextIndex = (currentIndex + 1) % charSet.length;
  return charSet[nextIndex];
}

export function getPreviousChar(
  currentChar: string,
  charSet: string = CHAR_SET
): string {
  const currentIndex = getSafeIndex(currentChar, charSet);
  const prevIndex = (currentIndex - 1 + charSet.length) % charSet.length;
  return charSet[prevIndex];
}

export function getBestCharSet(text: string): string {
  // Check if it's purely numeric (excluding spaces)
  if (/^[0-9 ]+$/.test(text)) {
    return NUMERIC_SET;
  }

  // Check if it's a time-like string (numbers, colon, space)
  if (/^[0-9: ]+$/.test(text)) {
    return TIME_SET;
  }

  // Default to alphanumeric
  return ALPHANUMERIC_SET;
}

export const NUMERIC_SET = " 0123456789";
export const TIME_SET = " 0123456789:";
export const ALPHANUMERIC_SET = " ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789:-.>";
export const CHAR_SET = ALPHANUMERIC_SET;
